export const ease = [0.44, 0, 0.56, 1] as const;
export const springUI = { type: 'spring', duration: 0.4, bounce: 0.2 } as const;
export const springSnappy = { type: 'spring', duration: 0.35, bounce: 0.18 } as const;
export const reveal = { type: 'tween', duration: 0.55, ease } as const;

implementation_recipes.section_reveal:
export function Reveal({ as: Tag = motion.section, ...p }) {
  return <Tag initial={{ opacity: 0, y: 28 }} whileInView={{ opacity: 1, y: 0 }} viewport={{ once: true, amount: 0.2 }} transition={reveal} {...p} />;
}

implementation_recipes.header_scroll:
const sentinel = useRef(null);
const [scrolled, set] = useState(false);
useEffect(() => { const f = () => set(sentinel.current.getBoundingClientRect().top <= 0); f(); addEventListener('scroll', f, { passive: true }); return () => removeEventListener('scroll', f); }, []);
<motion.nav animate={{ backgroundColor: scrolled ? '#fff' : 'rgba(255,255,255,0)' }} transition={springSnappy} className="fixed inset-x-0 top-0 z-10 h-[72px] after:absolute after:inset-x-0 after:bottom-0 after:border-b" style={{ '--tw-border': scrolled ? 'rgba(138,138,138,0.2)' : 'transparent' }} />
// attach ref={sentinel} to the page's target block (home: hero 'Text & Form').

implementation_recipes.marquee:
function Ticker({ children, reverse, speed = 10 }) {
  const x = useMotionValue(0); const ref = useRef(null); const hovered = useRef(false); const w = useRef(0); const factor = useSpring(1, { stiffness: 100, damping: 20 });
  useEffect(() => { w.current = ref.current.scrollWidth / 2; }, []);
  useAnimationFrame((_, dt) => { const v = speed * factor.get() * dt / 1000; let n = x.get() + (reverse ? v : -v); if (n <= -w.current) n += w.current; if (n > 0) n -= w.current; x.set(n); });
  return <div className="overflow-hidden [mask-image:linear-gradient(90deg,transparent_0%,#000_8.24%,#000_91.04%,transparent_100%)]" onMouseEnter={() => factor.set(0.9)} onMouseLeave={() => factor.set(1)}>
    <motion.ul ref={ref} style={{ x }} className="flex gap-6 w-max">{children}{children}</motion.ul></div>;
}

implementation_recipes.cursor_follow:
function DiscoverCursor({ active }) {
  const mx = useMotionValue(0), my = useMotionValue(0);
  const cfg = { stiffness: 500, damping: 60, mass: 1 };
  const x = useSpring(mx, cfg), y = useSpring(my, cfg);
  const [big, setBig] = useState(false);
  useEffect(() => { const m = e => { mx.set(e.clientX); my.set(e.clientY); }; addEventListener('pointermove', m); return () => removeEventListener('pointermove', m); }, []);
  useEffect(() => { if (!active) return setBig(false); const t = setTimeout(() => setBig(true), 100); return () => clearTimeout(t); }, [active]);
  if (!active) return null; // no exit animation
  return <motion.div style={{ x, y, translateX: '-50%', position: 'fixed', left: 0, top: 0, zIndex: 13, pointerEvents: 'none' }}>
    <motion.div animate={{ width: big ? 76 : 10, height: big ? 76 : 10 }} transition={springUI} className="rounded-full bg-[#1c6bcf] border-2 border-[rgba(0,36,84,0.2)] overflow-hidden grid place-items-center">
      <span className="text-white text-xs font-bold uppercase" style={{ opacity: big ? 1 : 0 }}>Discover</span></motion.div></motion.div>;
}
// set active via onPointerEnter/Leave on the services grid; skip on (hover: none) devices.
